import { Component, ViewChild, ChangeDetectorRef } from '@angular/core';
import { Credito } from '../../models/credito.model';
import { ActivatedRoute, RouterLink } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { CreditoAbono } from '../../models/credito.abono';
import { CreditoAbonoService } from '../../controllers/credito.abono.service';
import { EstadoCuenta, UtilsEstadoCuentaService } from '../../main/estado-cuenta/services/utils-estado-cuenta.service';
import { FileInputComponent } from "../../shared/file-input/file-input.component";
import { TableRow } from '../../shared/tabla/tabla.component';
import { UtilsService } from '../../services/utils.service';
import { CreditoService } from '../../controllers/credito.service';
import { DatePipe, CurrencyPipe } from '@angular/common';
import { FormularioFlotanteComponent } from '../../shared/formulario-flotante/formulario-flotante.component';
import { LocalStorageService } from '../../services/localStorage/local-storage.service';
import { PagoCargaMasiva } from '../../models/pago.carga.masiva';
import { VentanaPagoCreditoComponent } from './ventana-pago-credito/ventana-pago-credito.component';
import { Output, EventEmitter } from '@angular/core';

@Component({
  selector: 'app-abono-cancelacion',
  imports: [
    RouterLink,
    FormsModule,
    DatePipe,
    CurrencyPipe,
    VentanaPagoCreditoComponent,
    FormularioFlotanteComponent
  ],
  templateUrl: './abono-cancelacion.component.html',
  styleUrl: './abono-cancelacion.component.css'
})
export class AbonoCancelacionComponent {
  @ViewChild('fileInput')
  fileInput: FileInputComponent | undefined
  credito_id?: number  
  abonos: (CreditoAbono & TableRow)[] = []
  abono: Partial<CreditoAbono> = {}
  showAdd: boolean = false
  ultimoEstado?: EstadoCuenta  
  nota: string = ''
  formExtra = { id: 0 }

  credito?: Credito
  cargaMasivaEdit?: PagoCargaMasiva;

  showDeleteForm: boolean = false;

  @Output() eliminarAbono = new EventEmitter<{ abono: Partial<CreditoAbono>, nota: string }>();
  constructor(
    public abonoController: CreditoAbonoService,
    private route: ActivatedRoute,
    public utils: UtilsService,
    private utilsEstadoCuenta: UtilsEstadoCuentaService,
    private creditoController: CreditoService,    
    private cd: ChangeDetectorRef
  ) { }

  ngOnInit() {
  this.route.paramMap.subscribe(async (params) => {
      const id = this.utils.intOrNull(params.get('credito_id'))
      if (id) {
        this.setCreditoById(id)
      }
    })
  }

  totalAbonos() {
    return this.abonos
      .filter((item) => !item.deleted_at)
      .reduce((acc, item) => {
        return acc + item.monto
      }, 0)
  }
    


  async abrirEditorCargaMasiva(abono: CreditoAbono): Promise<void> {    
    this.abono = abono;      
    // Asigna la carga masiva asociada al abono, si existe
    this.cargaMasivaEdit = abono.pagos_cargas_masivas
    this.showDeleteForm = true;    
  }

  async deleteAbonoDesdePadre(event: { abono: Partial<CreditoAbono>, nota: string }) {
    await this.abonoController.switch(event.abono, { nota: event.nota });
    await this.creditoController.actualizarEstadoCuenta(this.credito_id)
    this.abono = {};    
    this.showDeleteForm = false;
  }

  private async setCreditoById(id: number) {
    this.credito_id=id
    this.credito= await this.creditoController.find(id,[
      'creditosPagos',
      'abonos',
      'abonos.pagosCargasMasivas',
      'abonos.usuarios',
      'datosPersonaFisica.datosPersonales',
      'datosPersonasMorales.representanteLegal',
      'productosFinancieros.plazos', 
      'estadoCuenta', 
      'convenios.conveniosPagos'])
    this.abonos= this.credito?.abonos??[]    
     this.cd.detectChanges(); 
  }

}
