import { Component, ViewChild } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { CreditoService } from '../../controllers/credito.service';
import { Credito } from '../../models/credito.model';
import { CurrencyPipe} from '@angular/common';
import { ViewResumenClienteComponent } from "../../main/estado-cuenta/shared/view-resumen-cliente/view-resumen-cliente.component";
import { BuscadorCreditosComponent } from "../../main/estado-cuenta/shared/buscador-creditos/buscador-creditos.component";
import { ViewRelacionAbonosComponent } from "../../main/estado-cuenta/shared/view-relacion-abonos/view-relacion-abonos.component";
import { CreditoAbono } from '../../models/credito.abono';
import { FormsModule } from '@angular/forms';
import { AbonoMasivoComponent } from '../carga-masiva/abono-masivo/abono-masivo.component';
import { CreditoAbonoService } from '../../controllers/credito.abono.service';
import { UtilsEstadoCuentaService } from '../../main/estado-cuenta/services/utils-estado-cuenta.service';
import { UtilsService } from '../../services/utils.service';

@Component({
    selector: 'app-pagos-traspaso',
    imports: [
    CurrencyPipe,
    BuscadorCreditosComponent,
    ViewRelacionAbonosComponent,
    FormsModule
],
    templateUrl: './pagos-traspaso.component.html',
    styleUrl: './pagos-traspaso.component.css'
})
export class PagosTraspasoComponent {
  @ViewChild('relacionAbonosReceptor') relacionAbonosReceptor?: ViewRelacionAbonosComponent 
  credito?:Credito
  creditoReceptor?:Credito
  abonoAtraspasar?:CreditoAbono
  relations= ['creditosPagos', 'abonos', 'abonos.pagosCargasMasivas', 'abonos.usuarios', 'productosFinancieros.plazos', 'convenios.conveniosPagos', 'estadoCuenta']
  notaTraspaso:string=''

  constructor(
    private abonoController:CreditoAbonoService,
    public creditoController: CreditoService,
    private route: ActivatedRoute,
    private utilsEstadoCuenta: UtilsEstadoCuentaService,
    public utils: UtilsService
  ) { }

  ngOnInit() {
    this.route.params.subscribe(async (params) => {
      if (params['credito_id']) {
        this.notaTraspaso=''
        this.setCreditoById(params['credito_id'])
      }
    })
  }

  private async setCreditoById(id: number) {
    this.credito = await this.creditoController.find(id, this.relations)
    console.log(this.credito)
  }

  public async traspasar(){
    if(!this.abonoAtraspasar || !this.notaTraspaso || !this.creditoReceptor?.abonos) return;
    let nota= 'ABONO CREADO POR TRASPASO: '+this.notaTraspaso

    const res = await this.abonoController.switch(this.abonoAtraspasar.id, { nota })
    if(res){
      const nuevoAbono= await this.abonoController.new({
        ...this.abonoAtraspasar,
        id:0,
        credito_id:this.creditoReceptor.id,
        comentarios:nota,
      })
      if(nuevoAbono){
        this.credito?.abonos?.splice(this.credito.abonos.indexOf(this.abonoAtraspasar),1)
        this.creditoReceptor.abonos.push(nuevoAbono)
        this.relacionAbonosReceptor?.setData()
        this.utilsEstadoCuenta.calculateEstadoDeCuenta(this.credito, true)
      }
    }
  }
}
