import { Component } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { CreditoService } from '../../controllers/credito.service';
import { Credito } from '../../models/credito.model';
import { ViewResumenCreditoComponent } from "../../main/estado-cuenta/shared/view-resumen-credito/view-resumen-credito.component";

import { ViewRelacionAbonosComponent } from "../../main/estado-cuenta/shared/view-relacion-abonos/view-relacion-abonos.component";
import { FormsModule } from '@angular/forms';

@Component({
    selector: 'app-pagos-cancelacion',
    imports: [
    ViewResumenCreditoComponent,
    ViewRelacionAbonosComponent,
    FormsModule
],
    templateUrl: './pagos-cancelacion.component.html',
    styleUrl: './pagos-cancelacion.component.css'
})
export class PagosCancelacionComponent {
  credito?:Credito
  comentarios:string=''

  constructor(
    public creditoController: CreditoService,
    private route: ActivatedRoute,
  ) { }

  ngOnInit() {
    this.route.params.subscribe(async (params) => {
      if (params['credito_id']) {
        this.setCreditoById(params['credito_id'])
      }
    })
  }

  private async setCreditoById(id: number) {
    this.credito = await this.creditoController.find(id, ['creditosPagos', 'abonos', 'abonos.pagosCargasMasivas', 'abonos.usuarios', 'productosFinancieros.plazos'])
    console.log(this.credito)
  }
}
